export const icon=name=>`<svg viewBox="0 0 256 256" fill="currentColor" aria-hidden="true">${iconShapes[name]??iconShapes.info}</svg>`;
export const button=(action,label,ic,extra='',id='')=>`<button type="button" class="icon-btn ${extra}" data-action="${action}" ${id?`data-id="${id}"`:''} aria-label="${esc(label)}">${icon(ic)}</button>`;
// Concrete local assets are mapped here; no network request occurs in the demo.
export const coverPath=id=>`./assets/v5/cover-${id}.jpg`;
export const cover=(id,extra='',alt=true)=>`<img class="cover ${extra}" src="${coverPath(id)}" alt="${alt?esc(`Capa de ${book(id).title}`):''}" width="200" height="300" draggable="false">`;
export const avatar=p=>`<span class="avatar">${cover(p.books[0],'',false)}</span>`;
export const empty=(title,body,action='')=>`<section class="empty"><span class="empty-mark">${icon('discover')}</span><h2>${esc(title)}</h2><p>${esc(body)}</p>${action}</section>`;
export const portrait=(name,index=0)=>`<div class="portrait portrait-${index}" role="img" aria-label="Ilustração fictícia de ${esc(name)}"><span>${esc(name[0])}</span><small>Ilustração</small></div>`;
